// audio.js — all sound is synthesised with WebAudio. No audio files, no network.
// SFX: gunshot, punch, pickup, crash, siren, mission jingle, engine hum, UI clicks.
// Music: a small looping synthwave bassline + hats, generated by a step sequencer.
export function createAudio() {
  const A = {
    ctx: null, master: null, musicGain: null, engineOsc: null, engineGain: null,
    enabled: true, musicOn: true, step: 0, nextStep: 0, sirenOn: false,
    init() {
      if (this.ctx) return;
      try {
        this.ctx = new (window.AudioContext || window.webkitAudioContext)();
        this.master = this.ctx.createGain(); this.master.gain.value = 0.5;
        this.master.connect(this.ctx.destination);
        this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = 0.16;
        this.musicGain.connect(this.master);
        // Engine hum: two detuned saws through a lowpass, gain follows speed.
        this.engineOsc = this.ctx.createOscillator(); this.engineOsc.type = 'sawtooth';
        this.engineOsc.frequency.value = 55;
        const o2 = this.ctx.createOscillator(); o2.type = 'sawtooth'; o2.frequency.value = 82;
        this.engineGain = this.ctx.createGain(); this.engineGain.gain.value = 0;
        const lp = this.ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 420;
        this.engineOsc.connect(lp); o2.connect(lp); lp.connect(this.engineGain); this.engineGain.connect(this.master);
        this.engineOsc.start(); o2.start(); this.engineOsc2 = o2;
        this.nextStep = this.ctx.currentTime + 0.1;
      } catch (e) { this.ctx = null; }
    },
    resume() { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); },
    setEngine(speed01, on) {
      if (!this.ctx) return;
      const t = this.ctx.currentTime;
      this.engineGain.gain.setTargetAtTime(on ? 0.05 + speed01 * 0.06 : 0, t, 0.1);
      this.engineOsc.frequency.setTargetAtTime(50 + speed01 * 110, t, 0.1);
      this.engineOsc2.frequency.setTargetAtTime(75 + speed01 * 160, t, 0.1);
    },
    blip(freq, dur, type = 'square', vol = 0.2, slide = 0) {
      if (!this.ctx || !this.enabled) return;
      const t = this.ctx.currentTime;
      const o = this.ctx.createOscillator(), g = this.ctx.createGain();
      o.type = type; o.frequency.setValueAtTime(freq, t);
      if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
      g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
      o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.02);
    },
    noise(dur, vol = 0.3, freq = 1200) {
      if (!this.ctx || !this.enabled) return;
      const t = this.ctx.currentTime;
      const len = Math.floor(this.ctx.sampleRate * dur);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
      const src = this.ctx.createBufferSource(); src.buffer = buf;
      const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = freq;
      const g = this.ctx.createGain(); g.gain.value = vol;
      src.connect(f); f.connect(g); g.connect(this.master); src.start(t);
    },
    gunshot() { this.noise(0.14, 0.5, 2600); this.blip(160, 0.08, 'square', 0.25, -100); },
    punch() { this.noise(0.08, 0.3, 700); },
    crash() { this.noise(0.3, 0.45, 500); this.blip(70, 0.25, 'sawtooth', 0.3, -30); },
    pickup() { this.blip(660, 0.09, 'sine', 0.25); setTimeout(() => this.blip(990, 0.12, 'sine', 0.25), 70); },
    click() { this.blip(520, 0.05, 'square', 0.12); },
    denied() { this.blip(180, 0.15, 'square', 0.18, -60); },
    sirenBurst() { this.blip(880, 0.35, 'sine', 0.12, 220); },
    wantedUp() { this.blip(220, 0.12, 'sawtooth', 0.2); setTimeout(() => this.blip(330, 0.18, 'sawtooth', 0.2), 110); },
    missionJingle() {
      [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => this.blip(f, 0.22, 'triangle', 0.25), i * 110));
    },
    failJingle() { [400, 300, 200].forEach((f, i) => setTimeout(() => this.blip(f, 0.25, 'sawtooth', 0.2), i * 140)); },
    // Music sequencer: call every frame; schedules 8th-note steps ahead of time.
    musicTick() {
      if (!this.ctx || !this.musicOn || !this.enabled) return;
      const spb = 60 / 112 / 2; // 112 BPM, 8th notes
      const bass = [55, 0, 55, 0, 65.4, 0, 49, 0, 55, 0, 55, 0, 82.4, 0, 73.4, 0];
      const lead = [220, 0, 0, 261.6, 0, 0, 329.6, 0, 0, 392, 0, 0, 329.6, 0, 261.6, 0];
      while (this.nextStep < this.ctx.currentTime + 0.15) {
        const i = this.step % 16, t = this.nextStep;
        if (bass[i]) this.noteAt(bass[i], t, spb * 0.95, 'sawtooth', 0.5, 300);
        if (lead[i]) this.noteAt(lead[i], t, spb * 0.9, 'triangle', 0.22, 1800);
        if (i % 2 === 0) this.hatAt(t, i % 4 === 2 ? 0.06 : 0.03);
        this.step++; this.nextStep += spb;
      }
    },
    noteAt(freq, t, dur, type, vol, cutoff) {
      const o = this.ctx.createOscillator(), g = this.ctx.createGain();
      const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = cutoff;
      o.type = type; o.frequency.value = freq;
      g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
      o.connect(f); f.connect(g); g.connect(this.musicGain); o.start(t); o.stop(t + dur + 0.02);
    },
    hatAt(t, vol) {
      const len = Math.floor(this.ctx.sampleRate * 0.03);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
      const s = this.ctx.createBufferSource(); s.buffer = buf;
      const f = this.ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 6000;
      const g = this.ctx.createGain(); g.gain.value = vol;
      s.connect(f); f.connect(g); g.connect(this.musicGain); s.start(t);
    },
  };
  return A;
}
